async function loadWorkbook(source) {
  try {
    let data;
    if (source) {
      data = await source.arrayBuffer();
    } else {
      const response = await fetch(workbookFile);
      if (!response.ok) throw new Error(`HTTP ${response.status} fetching ${workbookFile}`);
      data = await response.arrayBuffer();
    }

    state.workbook = XLSX.read(new Uint8Array(data), { cellDates: true });
    if (!state.workbook.SheetNames.length) throw new Error('No sheets found in workbook');
    state.sheets = parseSheets(state.workbook);
    state.active = 0;
    state.query = '';
    renderNavigation();
    summaryCards();
    renderTable();
    toast(`Workbook loaded successfully - ${state.sheets.length} sheets found`);
  } catch (error) {
    console.error('Error loading workbook:', error);
    toast(`Error loading workbook: ${error.message}`);
    qs('#tableMount').innerHTML = `<div class="empty-state"><strong>Workbook Load Error</strong><p>${escapeHtml(error.message)}</p></div>`;
  }
}
